using Confectory.Core;
using System.Text.Json.Nodes;

// Original local names label existing input/output storage; no value copy or new source authority.
internal static class BlueprintAliases
{
 public static JsonObject Prepare(JsonObject request)
 {
  var graph=request["graph"]!.DeepClone().AsObject();var feature=new Parser(request["featureSource"]!.GetValue<string>(),"<alias-feature>").ParseElement();
  if(feature.Kind!="function"||graph["feature"]?.ToString()!=feature.Id||graph["nodes"]!.AsArray().Any(n=>n!["implementationContext"] is not null||n["forwardCallerStorage"]?.GetValue<bool>()==true))throw new ArgumentException("Ordinary owned root alias plan required");
  var plan=request["plan"]!.AsObject();if(plan.Any(p=>p.Key is not ("aliases" or "bindings"))||plan["aliases"] is not JsonArray edits||edits.Count is <1 or >64||plan["bindings"] is not JsonArray bindings||bindings.Count>128)throw new ArgumentException("Bounded alias names and binding plan required");
  string profile=graph["profile"]!.ToString();if(profile is FeatureBlueprint.Profile or FeatureBlueprint.ImplicitProfile or FeatureBlueprint.MultiOutputProfile or FeatureBlueprint.LocalsProfile or FeatureBlueprint.RefNodesProfile or FeatureBlueprint.ExternalRefsProfile)graph["profile"]=FeatureBlueprint.AliasLocalsProfile;
  else if(!FeatureBlueprint.SupportsPrivateGraphs(profile)&&profile!=FeatureBlueprint.AliasLocalsProfile)throw new ArgumentException("Current alias profile required");
  graph["locals"]??=new JsonArray();var locals=graph["locals"]!.AsArray();var ids=new HashSet<string>(StringComparer.Ordinal);
  JsonObject Source(JsonNode value){var source=value.AsObject();if(source.Count==1&&source["input"] is JsonValue)return new(){["input"]=source["input"]!.DeepClone()};if(source["node"] is JsonValue&&source.Count is 1 or 2&&source.All(p=>p.Key is "node" or "output"))return new(){["node"]=source["node"]!.DeepClone(),["output"]=source["output"]?.DeepClone()??JsonValue.Create("return")};throw new ArgumentException("Existing input or node output storage required");}
  string SourceType(JsonObject source){if(source["input"] is not null)return feature.Signature!.Args.Single(p=>!p.IsOut&&p.Name==source["input"]!.ToString()).Type;var node=graph["nodes"]!.AsArray().Single(n=>n!["id"]!.ToString()==source["node"]!.ToString())!;var signature=node["signature"]!;string output=source["output"]!.ToString();return output=="return"&&signature["return"]!.ToString()!="void"?signature["return"]!.ToString():signature["args"]!.AsArray().Single(p=>p!["mode"]?.ToString()=="out"&&p["name"]!.ToString()==output)!["type"]!.ToString();}
  foreach(var edit in edits){var row=edit!.AsObject();if(row.Count!=4||row.Any(p=>p.Key is not ("id" or "name" or "type" or "sourceJson")))throw new ArgumentException("Exact alias fields required");string id=row["id"]!.ToString(),name=row["name"]!.GetValue<string>().Trim(),type=row["type"]!.ToString();if(!System.Text.RegularExpressions.Regex.IsMatch(id,@"\A[A-Za-z_][A-Za-z_0-9.-]{0,127}\z")||!ids.Add(id)||name.Length is <1 or >60||name.Any(char.IsControl))throw new ArgumentException("Unique alias identity and nonempty display name required");var source=Source(JsonNode.Parse(row["sourceJson"]!.GetValue<string>())!);if(SourceType(source)!=type)throw new ArgumentException("Alias must preserve the exact storage type");var prior=locals.SingleOrDefault(x=>x!["id"]!.ToString()==id);if(prior is not null&&(prior["source"] is null||prior["type"]!.ToString()!=type||!JsonNode.DeepEquals(Source(prior["source"]!),source)))throw new ArgumentException("Retargeting existing alias storage is not a rename");if(locals.Any(x=>x!["id"]!.ToString()!=id&&(x["name"]!.ToString()==name||x["source"] is not null&&JsonNode.DeepEquals(Source(x["source"]!),source))))throw new ArgumentException("Choose a distinct local name; this storage may already have a name");var replacement=new JsonObject{["id"]=id,["name"]=name,["type"]=type,["source"]=source};if(prior is null)locals.Add(replacement);else locals[locals.IndexOf(prior)]=replacement;}
  if(locals.Count>64)throw new ArgumentException("Local value budget");
  foreach(var value in bindings){var b=value!.AsObject();if(b.Any(p=>p.Key is not ("kind" or "node" or "name" or "valueJson")))throw new ArgumentException("Exact same-graph binding required");var binding=JsonNode.Parse(b["valueJson"]!.GetValue<string>());string name=b["name"]!.ToString();if(b["kind"]!.ToString()=="argument"){var node=graph["nodes"]!.AsArray().Single(n=>n!["id"]!.ToString()==b["node"]!.ToString())!;if(!node["arguments"]!.AsObject().ContainsKey(name))throw new ArgumentException("Existing input binding required");node["arguments"]![name]=binding;}else if(b["kind"]!.ToString()=="exit"&&graph["exits"]!.AsObject().ContainsKey(name))graph["exits"]![name]=binding;else throw new ArgumentException("Declared argument or root output required");}
  return new(){["graph"]=graph,["sourceWritten"]=false,["compiled"]=false,["executed"]=false};
 }
}
